import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface TableProps extends React.TableHTMLAttributes<HTMLTableElement> {}
export interface TableRowProps extends React.HTMLAttributes<HTMLTableRowElement> {
  /** 2px rules, ink cells. */
  total?: boolean;
}
export interface TableCellProps extends React.TdHTMLAttributes<HTMLTableCellElement> {
  total?: boolean;
}
export interface TableHeaderCellProps extends React.ThHTMLAttributes<HTMLTableCellElement> {}


const styles = stylex.create({
  table: {
    width: {
      default: "calc(100% + 40px)",
      [mq.phone]: "calc(100% + 2 * var(--pad))",
    },
    borderCollapse: "collapse",
    marginTop: 16,
    marginBottom: 24,
    marginLeft: {
      default: -20,
      [mq.phone]: "calc(-1 * var(--pad))",
    },
    marginRight: {
      default: 0,
      [mq.phone]: "calc(-1 * var(--pad))",
    },
    fontSize: {
      default: 14,
      [mq.phone]: 16,
    },
  },
  th: {
    textAlign: {
      default: "left",
      ":last-child": "right",
    },
    fontWeight: 600,
    color: "var(--text)",
    letterSpacing: "-0.01em",
    paddingTop: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingBottom: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingLeft: {
      default: 12,
      ":first-child": 20,
      [mq.phone]: 12,
    },
    paddingRight: {
      default: 16,
      ":last-child": 20,
      [mq.phone]: 12,
    },
    borderBottomWidth: 2,
    borderBottomStyle: "solid",
    borderBottomColor: raster.divider,
    fontSize: {
      default: 13,
      [mq.phone]: 15,
    },
  },
  td: {
    paddingTop: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingBottom: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingLeft: {
      default: 12,
      ":first-child": 20,
      [mq.phone]: 12,
    },
    paddingRight: {
      default: 16,
      ":last-child": 20,
      [mq.phone]: 12,
    },
    color: raster.gray,
    fontWeight: 500,
    letterSpacing: "-0.01em",
    borderBottomWidth: raster.hairline,
    borderBottomStyle: "solid",
    borderBottomColor: raster.divider,
    verticalAlign: "top",
    textAlign: {
      default: "left",
      ":last-child": "right",
    },
  },
  row: {
    backgroundColor: {
      default: "transparent",
      ":nth-child(even)": "var(--table-alt)",
    },
  },
  total: {
    fontWeight: 500,
    color: "var(--text)",
    borderTopWidth: 2,
    borderTopStyle: "solid",
    borderTopColor: raster.divider,
    borderBottomWidth: 2,
    borderBottomStyle: "solid",
    borderBottomColor: raster.divider,
    backgroundColor: "transparent",
  },
  totalCell: {
    fontWeight: 500,
    color: "var(--text)",
    borderTopWidth: 2,
    borderBottomWidth: 2,
  },
});

/** Open grid, 1px row rules, last column right-aligned. */
export const Table = React.forwardRef<HTMLTableElement, TableProps>(function Table(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-table", className], styles.table);
  return <table ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

export function TableHead({ className, style, ...props }: React.HTMLAttributes<HTMLTableSectionElement>) {
  return <thead className={className} style={style} {...props} />;
}

export function TableBody({ className, style, ...props }: React.HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody className={className} style={style} {...props} />;
}

export function TableRow({ total, className, style, ...props }: TableRowProps) {
  const sx = rs([total && "rs-total-row", className, "rs-table-row"], styles.row, total && styles.total);
  return <tr {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function TableTh({ className, style, ...props }: TableHeaderCellProps) {
  const sx = rs([className, "rs-table-th"], styles.th);
  return <th {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function TableTd({ total, className, style, ...props }: TableCellProps) {
  const sx = rs([className, "rs-table-td", total && "rs-table-total-cell"], styles.td, total && styles.totalCell);
  return <td {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import type { CompiledStyles, InlineStyles } from "@stylexjs/stylex";
import { cx } from "./cx";

type Nested<T> = T | ReadonlyArray<Nested<T>>;

/** Exactly what stylex.props accepts: compiled leaves, falsy, nested arrays, or a leaf with inline styles. */
export type Leaves = ReadonlyArray<Nested<null | undefined | CompiledStyles | boolean | Readonly<[CompiledStyles, InlineStyles]>>>;

type StyleXProps = { className?: string; style?: CSSProperties };

/**
 * The one seam every component styles through: semantic rs-* class names
 * (the CSS-first contract, and what packages/core generates CSS for) merged
 * with the compiled StyleX leaves that paint the React tree.
 */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: Leaves): StyleXProps {
  const sx = stylex.props(...styles) as StyleXProps;
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

